SELECT id, company_id,
       DATE_FORMAT(period, '%Y-%m-%d') AS period,
       summary_md, kpi_json, advice_md, llm_used, create_time
FROM opc_insight_daily_report
WHERE company_id = #{companyId}
  AND period >= #{from}
  AND period <= #{to}
ORDER BY period DESC

    LIMIT #{limit}

SELECT id, company_id,
       DATE_FORMAT(period, '%Y-%m-%d') AS period,
       summary_md, kpi_json, advice_md, llm_used, create_time
FROM opc_insight_daily_report
WHERE company_id = #{companyId}
  AND period = #{period}
